package com.ping.verification;
import java.util.*;
import com.ping.auth.*;import com.ping.event.*;import com.ping.encounter.*;import com.ping.interest.*;import com.ping.participant.*;import com.ping.support.TestBrowser;import com.ping.web.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.test.context.ActiveProfiles;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:h2:mem:work-integration;MODE=MySQL;DB_CLOSE_DELAY=-1","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.hibernate.ddl-auto=validate"}) @ActiveProfiles("integration-test")
class WorkIntegrationTests {
 @Autowired org.springframework.web.servlet.resource.ResourceUrlProvider assetUrls;
 @Autowired EventService events;@Autowired EncounterService encounters;@Autowired TaxonomyAdminService taxonomy;@Autowired InterestTaxonomy presentation;@Autowired JdbcTemplate sql;@Autowired AccountService accounts;@Autowired ParticipantService participants;@Autowired PasswordEncoder passwords;@LocalServerPort int port;
 static final String PASSWORD="Una contraseña exclusiva para test2026";long general,regular,event;
 @BeforeEach void setup(){if(accounts.find("general@integration.test").isEmpty())accounts.bootstrap("general@integration.test",PASSWORD);general=accounts.find("general@integration.test").orElseThrow();String email=UUID.randomUUID()+"@integration.test";sql.update("insert into ping_accounts(email,password_hash,email_verified) values(?,?,true)",email,passwords.encode(PASSWORD));regular=accounts.find(email).orElseThrow();var f=new EventForm();f.setName("Evento ficticio "+UUID.randomUUID());event=events.create(f).getId();}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 void as(long id){var user=accounts.user(id);SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(user,null,user.getAuthorities()));}
 void login(TestBrowser browser,long id)throws Exception{browser.get("/login");assertThat(browser.post("/login",Map.of("email",accounts.user(id).email(),"password",PASSWORD)).statusCode()).isEqualTo(302);}
 @Test void oldOverLimitListsCanBeReducedExplicitlyWithoutSilentImport(){sql.update("update events set meeting_points=?,encounter_activities=? where id=?","Uno\nDos\nTres\nCuatro","Actividad previa",event);var f=new PointForm();f.setName("No debe esconder la lista");f.setDirections("Indicaciones");assertThatThrownBy(()->encounters.savePoint(event,null,f)).isInstanceOf(BusinessRuleException.class);assertThatThrownBy(()->encounters.importLegacy(event)).isInstanceOf(BusinessRuleException.class);assertThat(encounters.points(event)).isEmpty();encounters.legacy(event,"Uno\nDos\nTres","Actividad previa",events.get(event).getVersion());assertThat(events.get(event).isStructuredEncounter()).isFalse();encounters.importLegacy(event);encounters.importLegacy(event);assertThat(encounters.points(event)).hasSize(3);assertThat(encounters.activities(event)).hasSize(1);assertThat(events.get(event).getMeetingPoints()).isEqualTo("Uno\nDos\nTres");}
 @Test void sectionWritesPreserveOtherConfigurationAndRejectStaleVersion(){var legacy=EventForm.from(events.get(event));legacy.setEncounterWords("Luz");legacy.setDeliveryName("Mesa original");legacy.setDeliveryDirections("Patio");events.update(event,legacy);var form=EventSectionForm.from(events.get(event));form.setName("Nombre cambiado");form.setDeliveryName("Valor no enviado a entrega");events.section(event,false,form);assertThat(events.get(event).getDeliveryName()).isEqualTo("Mesa original");assertThat(events.get(event).getEncounterWords()).isEqualTo("Luz");assertThatThrownBy(()->events.section(event,true,form)).isInstanceOf(BusinessRuleException.class);var current=EventSectionForm.from(events.get(event));current.setDeliveryName("Mesa nueva");events.section(event,true,current);assertThat(events.get(event).getName()).isEqualTo("Nombre cambiado");}
 @Test void taxonomyUsesExplicitIdsAllowsMembershipOverlapRejectsCyclesAndStaleEdits(){as(general);long interest=sql.queryForObject("select min(id) from interests",Long.class);String root="test-"+UUID.randomUUID(),child=root+":child";var f=new TaxonomyForm();f.setNodeKey(root);f.setLabel("Familia de prueba");f.setInterestIds(List.of(interest));taxonomy.save(null,f);f=new TaxonomyForm();f.setNodeKey(child);f.setLabel("Subgrupo de prueba");f.setParent(root);f.setInterestIds(List.of(interest));taxonomy.save(null,f);assertThat(presentation.memberships().get(interest)).contains(root,child);var cycle=taxonomy.form(root);cycle.setParent(child);assertThatThrownBy(()->taxonomy.save(root,cycle)).isInstanceOf(BusinessRuleException.class);var first=taxonomy.form(child);var stale=taxonomy.form(child);first.setLabel("Nombre revisado");taxonomy.save(child,first);assertThatThrownBy(()->taxonomy.save(child,stale)).isInstanceOf(BusinessRuleException.class);var hide=taxonomy.form(root);hide.setActive(false);taxonomy.save(root,hide);assertThat(presentation.nodes()).noneMatch(n->n.key().equals(root)||n.key().equals(child));assertThat(sql.queryForObject("select count(*) from interests where id=?",Integer.class,interest)).isEqualTo(1);as(regular);assertThatThrownBy(()->taxonomy.save(null,fresh())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);}
 TaxonomyForm fresh(){var f=new TaxonomyForm();f.setNodeKey("forbidden");f.setLabel("No autorizado");return f;}
 @Test void taxonomyAndInlineEditorAreProtectedAndRenderNativeForms()throws Exception{accounts.assign(general,regular,event,true);try(var ordinary=new TestBrowser(port);var admin=new TestBrowser(port)){login(ordinary,regular);assertThat(ordinary.get("/interests/taxonomy").statusCode()).isEqualTo(403);assertThat(ordinary.post("/interests/taxonomy",Map.of("nodeKey","forbidden","label","No" )).statusCode()).isEqualTo(403);assertThat(ordinary.get("/events/"+event+"/encounters").body()).contains("id=\"essentials\"","Guardar entrega","data-editor-status");login(admin,general);assertThat(admin.get("/interests/taxonomy").statusCode()).isEqualTo(200);assertThat(admin.get("/interests/taxonomy/music:pop/edit").body()).contains("Lady Gaga","Clave estable");}}
 @Test void chosenPresetAppearsBesideAliasAndRetainsIdentityBalance()throws Exception{events.transition(event,EventStatus.OPEN);var f=new ParticipantForm();f.setAlias("Alias con rana");f.setEventId(event);long id=participants.create(f).id();accounts.bind(regular,id,event);participants.avatar(id,new Avatar("rana","corona","gafas","menta"));var view=participants.get(id);assertThat(view.avatar().animal()).isEqualTo("rana");assertThat(view.points()).isZero();assertThat(view.id()).isEqualTo(id);try(var browser=new TestBrowser(port)){login(browser,regular);String body=browser.get("/me").body();assertThat(body).contains("avatar-public",assetUrls.getForLookupPath("/img/avatars/animales/rana.svg"),assetUrls.getForLookupPath("/img/avatars/sombreros/corona.svg"),"Alias con rana");assertThat(body).doesNotContain("https://avatars.");}}
}
